la pod Śnieżnikiem山屋登向山顶的最后一段，不包含从山谷前往山屋的路程。", "notes": "仅截取并反转PTTK全长55.1公里路线的最后一段。此短段尚无独立核实的参数，因此留空。下载文件仅包含此段。"}}}}, {"kind": "trail", "body": {"peak_slug": "skalnik", "slug": "skalnik-czarnow-czartak-niebieski", "start_point_name": "Czarnów – węzeł przy dawnym Czartaku", "end_point_name": "Skalnik – rejon szczytu", "distance_km": null, "elevation_gain_m": null, "time_min": null, "difficulty": null, "route_type": "point-to-point", "active": true, "source_url": "https://dolnoslaskie.szlaki.pttk.pl/967-dolnoslaskie-przelecz-karpnicka-mianka", "last_verified_at": "2026-11-15T00:00:00Z", "map_url": "https://dolnoslaskie.szlaki.pttk.pl/967-dolnoslaskie-przelecz-karpnicka-mianka", "gpx_url": "https://raw.githubusercontent.com/Silentmaster86/peakguide/main/docs/catalogue/batch-02/routes/skalnik-czarnow-czartak-niebieski.gpx", "route_geometry": {"type": "MultiLineString", "coordinates": [[[15.91031423, 50.8010743], [15.9099508, 50.8012156], [15.90941448, 50.80131565], [15.90910392, 50.80123956], [15.90868202, 50.80122838], [15.90705366, 50.80131017], [15.90554585, 50.80118801]], [[15.90554585, 50.80118801], [15.9055753, 50.80142449], [15.90558091, 50.80210672], [15.90538171, 50.80264782], [15.90487919, 50.80317372], [15.90462951, 50.80328494], [15.90449328, 50.80338488], [15.90448314, 50.80353817], [15.90468092, 50.80370055], [15.90566812, 50.80402674], [15.90565377, 50.80415849], [15.904916, 50.80440674], [15.90461791, 50.80482379], [15.90434298, 50.80531645], [15.90393442, 50.80527346], [15.90276515, 50.80531382], [15.9024058, 50.80529355], [15.90111216, 50.80508418], [15.89972514, 50.80509372], [15.89879424, 50.80519395], [15.89854718, 50.80518023], [15.89843698, 50.80522729], [15.89848213, 50.80539634], [15.89842087, 50.80555541], [15.89826519, 50.80560841], [15.89639263, 50.80571569], [15.89462056, 50.80592204], [15.89381766, 50.80596136], [15.89343268, 50.80607252], [15.89325609, 50.80618566], [15.89316096, 50.80632546]], [[15.89316096, 50.80632546], [15.89391054, 50.80626024], [15.89459336, 50.806332], [15.8948919, 50.80650423], [15.8953459, 50.80662703], [15.89567064, 50.80691423], [15.89588788, 50.80703786], [15.89615273, 50.80712348], [15.89649142, 50.80720035], [15.89779804, 50.80729941], [15.89884209, 50.80744861], [15.90003292, 50.80801953], [15.90034999, 50.80825295], [15.90073544, 50.80864531]]]}, "geometry_source_url": "https://dolnoslaskie.szlaki.pttk.pl/item/gpx/967", "geometry_verified_at": "2026-11-15T00:00:00Z", "distance_source_url": null, "distance_verified_at": null, "elevation_gain_source_url": null, "elevation_gain_verified_at": null, "time_source_url": null, "time_verified_at": null, "i18n": {"pl": {"name": "Skalnik: niebieskim z Czarnowa przy dawnym Czartaku", "description": "Leśne podejście od węzła szlaków przy dawnym Czartaku do rejonu szczytu Skalnika. Nie obejmuje osobnego wejścia na skałę widokową Ostra Mała.", "notes": "GPX wycięto z trasy PTTK 31 km i odwrócono. Zachowano trzy części oryginału; nie dodano łączników. Metryki pełnego szlaku nie dotyczą tego podejścia i pozostają puste."}, "en": {"name": "Skalnik: blue trail from Czarnów near the former Czartak hut", "description": "A wooded ascent from the trail junction near the former Czartak hut to the Skalnik summit area. The separate Ostra Mała viewpoint ascent is excluded.", "notes": "The section was cut from the 31 km PTTK track and reversed, retaining three original pieces without added connectors. Whole-trail metrics do not describe this ascent and are left blank."}, "ua": {"name": "Скальник: синім маршрутом із Чарнова біля колишнього Czartak", "description": "Лісовий підйом від вузла стежок біля колишнього Czartak до вершини Скальника. Окремий підйом на оглядову скелю Ostra Mała не включено.", "notes": "Ділянку вирізано з 31-кілометрового треку PTTK і розвернуто, зберігши три початкові частини без нових з’єднань. Параметри повного маршруту тут не застосовуються й залишені порожніми."}, "zh": {"name": "Skalnik：从Czarnów原Czartak山屋附近沿蓝色步道上山", "description": "从原Czartak山屋附近步道交汇点经森林登向Skalnik山顶区域，不包含另行攀上Ostra Mała观景岩的路段。", "notes": "从PTTK全长31公里轨迹截取并反转，保留三个原始分段，未添加连接线。完整路线参数不适用于此登山段，因此留空。"}}}}, {"kind": "poi", "body": {"peak_slug": "sniezka", "type_slug": "viewpoint", "latitude": 50.735998, "longitude": 15.739546, "trail_id": null, "active": true, "source_url": "https://dolnoslaskie.szlaki.pttk.pl/1034-dolnoslaskie-sniezka", "last_verified_at": "2026-11-15T00:00:00Z", "website_url": "https://dolnoslaskie.szlaki.pttk.pl/1034-dolnoslaskie-sniezka", "google_maps_url": "https://www.google.com/maps/search/?api=1&query=50.735998,15.739546", "i18n": {"pl": {"name": "Śnieżka — panorama ze szczytu", "description": "Punkt widokowy na kopule szczytowej w pobliżu charakterystycznych zabudowań.", "tips": "Współrzędne pochodzą z karty PTTK. Aktualną dostępność sprawdź przed wyjściem."}, "en": {"name": "Śnieżka — summit panorama", "description": "A viewpoint on the summit dome near its distinctive buildings.", "tips": "Coordinates come from the PTTK entry. Check current access before departure."}, "ua": {"name": "Снєжка — панорама з вершини", "description": "Оглядова точка на вершині біля характерних споруд.", "tips": "Координати взято з картки PTTK. Перед виходом перевірте актуальний доступ."}, "zh": {"name": "Śnieżka山顶全景", "description": "位于山顶标志性建筑附近的观景位置。", "tips": "坐标来自PTTK资料。出发前请核实当前开放情况。"}}}}, {"kind": "poi", "body": {"peak_slug": "snieznik", "type_slug": "viewpoint", "latitude": 50.207895, "longitude": 16.847099, "trail_id": null, "active": true, "source_url": "https://dolnoslaskie.szlaki.pttk.pl/1932-dolnoslaskie-snieznik-rezerwat-wieza-widokowa", "last_verified_at": "2026-11-15T00:00:00Z", "website_url": "https://dolnoslaskie.szlaki.pttk.pl/1932-dolnoslaskie-snieznik-rezerwat-wieza-widokowa", "google_maps_url": "https://www.google.com/maps/search/?api=1&query=50.207895,16.847099", "i18n": {"pl": {"name": "Śnieżnik — wieża widokowa", "description": "Wieża w rejonie szczytu, otoczona chronioną przyrodą rezerwatu Śnieżnik Kłodzki.", "tips": "Współrzędne pochodzą z karty PTTK. Aktualną dostępność sprawdź przed wyjściem."}, "en": {"name": "Śnieżnik — observation tower", "description": "A tower in the summit area within the protected Śnieżnik Kłodzki landscape.", "tips": "Coordinates come from the PTTK entry. Check current access before departure."}, "ua": {"name": "Снєжник — оглядова вежа", "description": "Вежа у вершинній частині, серед охоронюваної природи резервату Śnieżnik Kłodzki.", "tips": "Координати взято з картки PTTK. Перед виходом перевірте актуальний доступ."}, "zh": {"name": "Śnieżnik观景塔", "description": "位于山顶区域，周边为Śnieżnik Kłodzki自然保护区。", "tips": "坐标来自PTTK资料。出发前请核实当前开放情况。"}}}}, {"kind": "poi", "body": {"peak_slug": "wielka-sowa", "type_slug": "viewpoint", "latitude": 50.680343, "longitude": 16.485569, "trail_id": null, "active": true, "source_url": "https://dolnoslaskie.szlaki.pttk.pl/1998-dolnoslaskie-wielka-sowa-wieza-widokowa", "last_verified_at": "2026-11-15T00:00:00Z", "website_url": "https://dolnoslaskie.szlaki.pttk.pl/1998-dolnoslaskie-wielka-sowa-wieza-widokowa", "google_maps_url": "https://www.google.com/maps/search/?api=1&query=50.680343,16.485569", "i18n": {"pl": {"name": "Wielka Sowa — wieża widokowa", "description": "Kamienna wieża na szczycie z panoramą otaczających pasm Sudetów.", "tips": "Współrzędne pochodzą z karty PTTK. Aktualną dostępność sprawdź przed wyjściem."}, "en": {"name": "Wielka Sowa — observation tower", "description": "A stone summit tower overlooking the surrounding Sudeten ranges.", "tips": "Coordinates come from the PTTK entry. Check current access before departure."}, "ua": {"name": "Велика Сова — оглядова вежа", "description": "Кам’яна вежа на вершині з панорамою довколишніх хребтів Судетів.", "tips": "Координати взято з картки PTTK. Перед виходом перевірте актуальний доступ."}, "zh": {"name": "Wielka Sowa观景塔", "description": "山顶石塔，可眺望周围苏台德山脉。", "tips": "坐标来自PTTK资料。出发前请核实当前开放情况。"}}}}, {"kind": "poi", "body": {"peak_slug": "szczeliniec-wielki", "type_slug": "trailhead", "latitude": 50.4807638, "longitude": 16.33994222, "trail_id": null, "active": true, "source_url": "https://dolnoslaskie.szlaki.pttk.pl/515-dolnoslaskie-przelecz-pod-szczelincem-szczeliniec-poczatek-schodow", "last_verified_at": "2026-11-15T00:00:00Z", "website_url": "https://dolnoslaskie.szlaki.pttk.pl/515-dolnoslaskie-przelecz-pod-szczelincem-szczeliniec-poczatek-schodow", "google_maps_url": "https://www.google.com/maps/search/?api=1&query=50.4807638,16.33994222", "i18n": {"pl": {"name": "Szczeliniec — początek schodów według PTTK", "description": "Punkt końcowy śladu edukacyjnego PTTK przy schodach, w pobliżu Karłowa. To nie parking ani wejście do kasy labiryntu.", "tips": "Pozycja jest końcowym punktem oficjalnego GPX. Sprawdź sezonowe zasady PNGS: https://pngs.gov.pl/komunikat-turystyczny"}, "en": {"name": "Szczeliniec — stairs endpoint in the PTTK track", "description": "The educational PTTK track ends at the stairs near Karłów. This is neither a parking location nor the labyrinth ticket entrance.", "tips": "The position is the endpoint of the official GPX. Check seasonal PNGS rules: https://pngs.gov.pl/komunikat-turystyczny"}, "ua": {"name": "Щелінець — точка сходів у треку PTTK", "description": "Кінцева точка навчального треку PTTK біля сходів поблизу Карлова. Це не паркінг і не вхід до каси лабіринту.", "tips": "Позиція відповідає кінцю офіційного GPX. Перевірте сезонні правила PNGS: https://pngs.gov.pl/komunikat-turystyczny"}, "zh": {"name": "Szczeliniec：PTTK轨迹标注的台阶端点", "description": "PTTK教育路线在Karłów附近台阶处的终点，并非停车场或岩石迷宫售票入口。", "tips": "位置为官方GPX终点。请核实PNGS季节性规定：https://pngs.gov.pl/komunikat-turystyczny"}}}}, {"kind": "poi", "body": {"peak_slug": "skalnik", "type_slug": "trailhead", "latitude": 50.801265, "longitude": 15.910256, "trail_id": null, "active": true, "source_url": "https://dolnoslaskie.szlaki.pttk.pl/2056-dolnoslaskie-czarnow-dawne-schronisko-czartak", "last_verified_at": "2026-11-15T00:00:00Z", "website_url": "https://dolnoslaskie.szlaki.pttk.pl/2056-dolnoslaskie-czarnow-dawne-schronisko-czartak", "google_maps_url": "https://www.google.com/maps/search/?api=1&query=50.801265,15.910256", "i18n": {"pl": {"name": "Czarnów — węzeł szlaków przy dawnym Czartaku", "description": "Punkt orientacyjny przy dawnym schronisku i węźle szlaków pod Skalnikiem.", "tips": "Wpis oznacza punkt szlaku. Nie potwierdza parkingu, noclegu ani czynnego schroniska."}, "en": {"name": "Czarnów — trail junction near the former Czartak hut", "description": "A reference point near the former hut and the trail junction below Skalnik.", "tips": "This entry marks a trail location. It does not confirm parking, accommodation or an operating hut."}, "ua": {"name": "Чарнув — вузол стежок біля колишнього Czartak", "description": "Орієнтир біля колишнього притулку та вузла маршрутів під Скальником.", "tips": "Запис позначає точку маршруту, не підтверджуючи паркінг, ночівлю чи діючий притулок."}, "zh": {"name": "Czarnów：原Czartak山屋附近步道交汇点", "description": "Skalnik山下原山屋及步道交汇处附近的参考位置。", "tips": "此条目仅标记步道位置，不代表已核实停车、住宿或山屋营业情况。"}}}}]$records$::jsonb) loop
 body=entry->'body';
 select id into peak from public.peaks where slug=body->>'peak_slug' and id=(case body->>'peak_slug' when 'sniezka' then 1 when 'snieznik' then 2 when 'wielka-sowa' then 6 when 'szczeliniec-wielki' then 11 when 'skalnik' then 8 end) and active=true for update;
 if peak is null then raise exception 'Peak missing or changed: %',body->>'peak_slug'; end if;
 body=body||jsonb_build_object('peak_id',peak);
 if entry->>'kind'='trail' then
  if exists(select from public.trails where slug=body->>'slug') then raise exception 'Trail slug already exists: %',body->>'slug'; end if;
  trail=jsonb_populate_record(null::public.trails,body);
 insert into public.trails (peak_id, slug, start_point_name, end_point_name, distance_km, elevation_gain_m, time_min, difficulty, route_type, active, source_url, last_verified_at, map_url, gpx_url, distance_source_url, distance_verified_at, elevation_gain_source_url, elevation_gain_verified_at, time_source_url, time_verified_at, route_geometry, geometry_source_url, geometry_verified_at) values (trail.peak_id, trail.slug, trail.start_point_name, trail.end_point_name, trail.distance_km, trail.elevation_gain_m, trail.time_min, trail.difficulty, trail.route_type, trail.active, trail.source_url, trail.last_verified_at, trail.map_url, trail.gpx_url, trail.distance_source_url, trail.distance_verified_at, trail.elevation_gain_source_url, trail.elevation_gain_verified_at, trail.time_source_url, trail.time_verified_at, trail.route_geometry, trail.geometry_source_url, trail.geometry_verified_at) returning id into saved_id;
 for lang,tr in select key,value from jsonb_each(body->'i18n') loop
 insert into public.trails_i18n (trail_id,lang,name, description, notes) values (saved_id,lang,tr->>'name', tr->>'description', tr->>'notes'); end loop;
 select jsonb_build_object('row',to_jsonb(r),'i18n',(select jsonb_agg(to_jsonb(i) order by i.lang) from public.trails_i18n i where trail_id=r.id)) into actual from public.trails r where id=saved_id;
 snapshot=snapshot||jsonb_build_array(jsonb_build_object('kind',entry->>'kind','id',saved_id,'snapshot',actual));
 else
  if exists(select from public.pois where peak_id=peak and source_url=body->>'source_url') then raise exception 'POI source already exists'; end if;
  select id into saved_id from public.poi_types where slug=body->>'type_slug';
  if saved_id is null then raise exception 'Missing POI type'; end if;
  body=body||jsonb_build_object('type_id',saved_id);
  poi=jsonb_populate_record(null::public.pois,body);
 insert into public.pois (peak_id, trail_id, type_id, latitude, longitude, active, source_url, last_verified_at, website_url, google_maps_url) values (poi.peak_id, poi.trail_id, poi.type_id, poi.latitude, poi.longitude, poi.active, poi.source_url, poi.last_verified_at, poi.website_url, poi.google_maps_url) returning id into saved_id;
 for lang,tr in select key,value from jsonb_each(body->'i18n') loop
 insert into public.pois_i18n (poi_id,lang,name, description, tips) values (saved_id,lang,tr->>'name', tr->>'description', tr->>'tips'); end loop;
 select jsonb_build_object('row',to_jsonb(r),'i18n',(select jsonb_agg(to_jsonb(i) order by i.lang) from public.pois_i18n i where poi_id=r.id)) into actual from public.pois r where id=saved_id;
 snapshot=snapshot||jsonb_build_array(jsonb_build_object('kind',entry->>'kind','id',saved_id,'snapshot',actual));
 end if;
 end loop;
 insert into peakguide_private.catalogue_batch_receipts(batch_key,snapshot)values('kgp-02',snapshot);
 raise notice 'Added 5 trails and 5 POIs, each in four languages';
end $batch$;
commit;
